      const shoulder = toRoot(upper);
      const pole = toRoot(lower).sub(shoulder.add(toRoot(hand)).multiplyScalar(0.5)).normalize();
      pole.lerp(new Vector3(s2 * 0.2, -1, -0.35).normalize(), w2);
