      const prox = this.bone(`${prefix}ThumbProximal`);
      if (!meta || !prox) continue;
      const flex = prox.position.clone().normalize().cross(U2.clone().negate()).normalize();
      prox.quaternion.slerp(new Quaternion().setFromAxisAngle(flex, 0.15), w2);
