    const v2 = new Vector3();
    for (const { node, isRotation, interpolant } of this.poseTracks) {
      const value = interpolant.evaluate(time);
      if (isRotation) node.quaternion.slerp(q2.fromArray(value), w2);
      else node.position.lerp(v2.fromArray(value), w2);
    }
    if (!this.poseLoop) return;
    const hips = this.bone("hips");
    const scale = this.height / 1.6;
    this.root.updateMatrixWorld(true);
    const contacts = [
      ["leftFoot", this.footRest?.left?.y],
      ["rightFoot", this.footRest?.right?.y],
      ["leftToes", this.toesRest?.left?.y],
      ["rightToes", this.toesRest?.right?.y],
      ["leftLowerLeg", 0.05 * scale],
      ["rightLowerLeg", 0.05 * scale],
      ["hips", 0.1 * scale],
      ["chest", 0.1 * scale],
      ["head", 0.1 * scale],
      ["leftHand", 0.03 * scale],
      ["rightHand", 0.03 * scale]
    ];
    let lowest = Infinity;
    for (const [name, clearance] of contacts) {
      const b2 = this.bone(name);
      if (!b2 || clearance == null) continue;
      lowest = Math.min(lowest, this.root.worldToLocal(b2.getWorldPosition(new Vector3())).y - clearance);
    }
    if (Number.isFinite(lowest)) hips.position.y -= lowest * w2;
